"use client";

import React, { forwardRef } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { CheckCircleIcon, CopyIcon } from "@phosphor-icons/react";
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard";
import { cn } from "@/lib/utils";

export interface CopyButtonProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onCopy"
> {
  /** The text or code string to copy to the clipboard */
  value: string;
  /** Label to display next to the icon in resting state (default: "Copy") */
  label?: React.ReactNode;
  /** Optional label override when copied (by default remains the same label) */
  copiedLabel?: React.ReactNode;
  /** Duration in milliseconds before resetting copied state (default: 1200) */
  timeout?: number;
  /** Render only the icon without text label */
  iconOnly?: boolean;
  /** Callback fired after successfully copying */
  onCopy?: (value: string) => void;
}

const uiEaseOut = [0.23, 1, 0.32, 1] as const;

/**
 * ══ CopyButton ═════════════════════════════════════════════════
 * Tactile copy-to-clipboard button featuring mechanical click yield,
 * subtle surface elevation, and a directional popLayout checkmark icon
 * animation between CopyIcon and filled CheckCircleIcon.
 * ═════════════════════════════════════════════════════════════════
 */
export const CopyButton = forwardRef<HTMLButtonElement, CopyButtonProps>(function CopyButton(
  {
    value,
    label = "Copy",
    copiedLabel,
    timeout = 1200,
    iconOnly = false,
    className,
    onClick,
    onCopy,
    children,
    title,
    disabled,
    ...props
  },
  ref
) {
  const { copied, copy } = useCopyToClipboard({ timeout, onCopy });
  const shouldReduceMotion = useReducedMotion();

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    onClick?.(e);
    if (!e.defaultPrevented && !disabled) {
      copy(value);
    }
  };

  const displayText = children ?? (iconOnly ? null : copied && copiedLabel ? copiedLabel : label);

  const iconVisible = { opacity: 1, transform: "translateY(0px)" };
  const iconInitial = shouldReduceMotion
    ? { opacity: 0, transform: "translateY(0px)" }
    : { opacity: 0, transform: "translateY(8px)" };
  const iconExit = shouldReduceMotion
    ? { opacity: 0, transform: "translateY(0px)" }
    : { opacity: 0, transform: "translateY(-8px)" };
  const iconTransition = {
    duration: shouldReduceMotion ? 0.14 : 0.18,
    ease: uiEaseOut,
  };

  return (
    <button
      ref={ref}
      type="button"
      disabled={disabled}
      onClick={handleClick}
      title={title || (copied ? "Copied to clipboard" : "Copy to clipboard")}
      aria-label={typeof displayText === "string" ? displayText : "Copy to clipboard"}
      className={cn(
        "group inline-flex h-7 cursor-pointer items-center justify-center gap-1.5 rounded-lg border px-2.5 text-xs font-medium shadow-2xs select-none",
        "transition-[color,background-color,border-color,box-shadow,transform] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] active:scale-[0.97]",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-900",
        "disabled:pointer-events-none disabled:opacity-40",
        copied
          ? "border-emerald-200 bg-emerald-50 text-emerald-700 shadow-[0_1px_2px_rgba(16,185,129,0.06)] dark:border-emerald-900/60 dark:bg-emerald-950/40 dark:text-emerald-400"
          : "border-slate-200/80 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50 hover:text-slate-900 dark:border-white/10 dark:bg-[#181818] dark:text-zinc-400 dark:hover:border-white/20 dark:hover:bg-[#252525] dark:hover:text-white",
        className
      )}
      {...props}
    >
      {/* Animated PopLayout Icon */}
      <span className="relative inline-grid size-[14px] shrink-0 overflow-hidden">
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            key={copied ? "copied" : "copy"}
            animate={iconVisible}
            initial={iconInitial}
            exit={iconExit}
            transition={iconTransition}
            className="col-start-1 row-start-1 flex size-[14px] items-center justify-center"
          >
            {copied ? (
              <CheckCircleIcon
                aria-hidden="true"
                size={14}
                weight="fill"
                className="text-emerald-600 dark:text-emerald-400"
              />
            ) : (
              <CopyIcon
                aria-hidden="true"
                size={14}
                weight="bold"
                className="text-slate-500 transition-colors group-hover:text-slate-900 dark:text-zinc-400 dark:group-hover:text-white"
              />
            )}
          </motion.span>
        </AnimatePresence>
      </span>

      {/* Text Label (stays "Copy") */}
      {displayText ? <span>{displayText}</span> : null}
    </button>
  );
});

"use client";

import { useState, useCallback, useRef, useEffect } from "react";

export interface UseCopyToClipboardOptions {
  /** Duration in milliseconds before resetting copied state (default: 2000) */
  timeout?: number;
  /** Optional callback fired when text is successfully copied */
  onCopy?: (text: string) => void;
}

export interface UseCopyToClipboardReturn {
  /** Whether text was recently copied to clipboard */
  copied: boolean;
  /** Function to copy text to clipboard */
  copy: (text: string) => Promise<boolean>;
}

/**
 * useCopyToClipboard
 *
 * Custom React hook to copy arbitrary text to the clipboard
 * with cross-browser fallback and automatic timeout reset.
 */
export function useCopyToClipboard({
  timeout = 2000,
  onCopy,
}: UseCopyToClipboardOptions = {}): UseCopyToClipboardReturn {
  const [copied, setCopied] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const copy = useCallback(
    async (text: string): Promise<boolean> => {
      if (!text && text !== "") return false;

      try {
        if (typeof navigator !== "undefined" && navigator?.clipboard?.writeText) {
          await navigator.clipboard.writeText(text);
        } else if (typeof document !== "undefined") {
          // Fallback for non-secure contexts or older browsers
          const textarea = document.createElement("textarea");
          textarea.value = text;
          textarea.style.position = "fixed";
          textarea.style.left = "-9999px";
          textarea.style.top = "-9999px";
          textarea.style.opacity = "0";
          document.body.appendChild(textarea);
          textarea.focus();
          textarea.select();
          document.execCommand("copy");
          document.body.removeChild(textarea);
        } else {
          return false;
        }

        setCopied(true);
        onCopy?.(text);

        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }

        timeoutRef.current = setTimeout(() => {
          setCopied(false);
          timeoutRef.current = null;
        }, timeout);

        return true;
      } catch (err) {
        console.error("Failed to copy to clipboard:", err);
        setCopied(false);
        return false;
      }
    },
    [timeout, onCopy]
  );

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return { copied, copy };
}
